//! Descriptions presented to MCP clients.

pub const LIST_PROJECTS: &str = "List projects registered in Lantern (local dev servers, tools, websites) with status, URL and port. Start here to see what exists and what is running. Shows the primary checkout's status and how many branch instances exist; use `list_instances` for per-branch detail, `get_project` for full config. Filters: `tag`; `kind` (project, service, tool, capability, website); `status` (running, stopped, starting, stopping, crashed, unhealthy, needs_config, external; `error` also accepted).";
pub const SEARCH_PROJECTS: &str = "Find projects by free text (case-insensitive substring of name, description, tags, or git branch names). Use when you remember only part of a name or want projects related to a topic such as \"browser\" or \"postgres\".";
pub const GET_PROJECT: &str = "Full details of one project: path, URLs, status, run command, health endpoint, dependencies, risk/confirmation metadata, docs and endpoint counts, and all its instances (branches). Pass `branch` or `instance` for that specific checkout instead of the primary.";
pub const LIST_INSTANCES: &str = "List instances (one per git checkout) with branch, status, port, URL, health, dirty flag and checkout path. Filter by `project`, `status` or `branch`. Use to see which branches are running side by side, or to find the instance id for other tools.";
pub const START_PROJECT: &str = "Start a project's dev server. Safe to repeat: if it is already running, reports its URL. Acts on the primary checkout unless `branch` (an existing instance) or `instance` is given; to run a branch with no instance yet use `start_branch`. Waits up to `wait_seconds` (default 30, max 55) for the server to accept connections; if still starting it returns an `operation_id` for `get_operation`.";
pub const STOP_PROJECT: &str = "Stop a project's dev server (its whole process group). Safe to repeat. Acts on the primary unless `branch`/`instance` is given. Deletes nothing. Check `get_dependencies` first if other projects rely on it.";
pub const RESTART_PROJECT: &str = "Restart a project's dev server (stop, then start). Acts on the primary unless `branch`/`instance` is given. Waits up to `wait_seconds` (default 40, max 55), then returns an `operation_id`.";
pub const START_BRANCH: &str = "Run a git branch of a project side by side with the others: creates a git worktree for `branch` if there is none (new branches start from `base`, default the primary's current branch), runs setup (copies .env, installs dependencies), starts it, and returns its own URL such as https://feature-x.myapp.glow. Safe to repeat; an existing instance is reused. Can take minutes: after `wait_seconds` (default 45, max 55) you get an `operation_id` and the work continues; poll `get_operation`. `start=false` only prepares the worktree.";
pub const GET_OPERATION: &str = "Check a long operation started by `start_project`, `start_branch`, `restart_project` or `call_tool_api` with `async=true`. Returns status (running, succeeded, failed, cancelled), the current step, and the error if it failed. `wait_seconds` (max 55) blocks until it finishes or the time passes, so you do not need to poll in a loop.";
pub const GET_PROJECT_LOGS: &str = "Recent log output (stdout and stderr, newest last) of a project's dev server. First stop when something fails to start or returns errors. `tail` lines (default 200, max 2000), `since` (\"15m\", \"2h\" or an ISO time), `stream` (stdout, stderr or all), `grep` (case-insensitive substring filter). Targets the primary unless `branch`/`instance` is given.";
pub const GET_PROJECT_DOCS: &str = "List or read a project's documentation files (README, AGENTS.md, CLAUDE.md, docs/**/*.md, plus anything its manifest lists). Without `path`: the list with kind and size. With `path`: the file text, paged by `offset`/`max_chars`. Reads the targeted branch's checkout, so the docs match that branch. Only listed files can be read.";
pub const GET_PROJECT_ENDPOINTS: &str = "List the HTTP API endpoints of a project (from its manifest and its OpenAPI/Swagger document): method, path, description, category, risk, body hint. Use before `call_tool_api`. `q` filters by substring of path, description or category; `limit` caps the list (default 200).";
pub const GET_PROJECT_DISCOVERY: &str = "Show how Lantern found a project's docs and endpoints: the auto-discovery settings (docs_auto, api_auto), discovered versus manual entries, sources tried, errors, last refresh time. Use to debug missing docs or endpoints.";
pub const REFRESH_DISCOVERY: &str = "Re-scan docs and re-fetch OpenAPI documents now (normally refreshed every 10 minutes and when a server starts). Pass a project/instance, or nothing to refresh all. Takes up to 30 seconds.";
pub const CHECK_HEALTH: &str = "Health of Lantern itself (dns, caddy, tls, daemon) and of every instance (healthy, unhealthy, unreachable, unknown; latency; last check). With `name` returns only that instance. `refresh=true` runs a check now instead of using the cached result.";
pub const GET_DEPENDENCIES: &str = "Dependency graph between projects (`depends_on` in manifests): what each needs and what depends on it. Pass `name` for one project. Check it before stopping or restarting something others rely on.";
pub const GET_PORTS: &str = "Show assigned ports by instance id, with status, health and URL. Matched hand-started listeners may add source, pid and branch. Use list_listeners for unmatched sockets; never guess a port.";
pub const LIST_LISTENERS: &str = "Raw list of TCP sockets listening on localhost with owning process, command line, working directory, and the matched project/instance. Finds servers started by hand in a terminal. Filters: `project`, `port`, `unmatched_only`.";
pub const LIST_TOOLS: &str = "List the tools agents can call through Lantern: projects of kind `tool` or `capability` (browser automation, data services, ...). Shows description, status, domain, risk, whether calls need confirmation, trigger keywords and endpoints. Then use `get_project_docs`, `get_project_endpoints` and `call_tool_api`. Filters: `tag`, `status`, `kind`.";
pub const CALL_TOOL_API: &str = "Call an HTTP API of a registered project through Lantern, e.g. tool=\"browser\", method=\"POST\", path=\"/tasks/execute\", body={...}. Lantern finds the running server's address; you give the project and a path. Returns the response body (cut at `max_bytes`, default 100000). Only registered projects are reachable. Endpoints marked risk high/critical, or projects needing confirmation, are not sent until `confirm=true`: ask the user first. For calls over ~50s set `async=true` to get a `job_id`, then use `get_operation` or `get_job_result`. See `get_project_endpoints` for what exists.";
pub const GET_JOB_RESULT: &str = "Fetch the result of an async `call_tool_api` job by `job_id`. While running: status and elapsed time. When done: the response body. On failure: the error. Jobs are kept for 1 hour after they finish. (`get_operation` returns the same job as an operation.)";
